// Package documents is the document area of a site (backend plan 4.11,
// decision O8): a folder tree with visibility rules (board only, owners,
// everyone, chosen units), a private folder per unit, documents that are
// uploaded or generated by the server, and the right of former occupants to
// the documents recipient to them. No versions.
package documents

import (
	"context"
	"errors"
	"slices"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"

	"github.com/openbekci/openbekci/server/internal/core/audit"
	"github.com/openbekci/openbekci/server/internal/core/authz"
	"github.com/openbekci/openbekci/server/internal/core/files"
	"github.com/openbekci/openbekci/server/internal/core/opsx"
	"github.com/openbekci/openbekci/server/internal/core/tenancy"
	"github.com/openbekci/openbekci/server/internal/platform/id"
	"github.com/openbekci/openbekci/server/internal/problem"
)

// Permissions of the module.
const (
	PermRead          authz.Permission = "documents.read"
	PermReadAddressed authz.Permission = "documents.read_addressed"
	PermManage        authz.Permission = "documents.manage"
	PermUploadOwn     authz.Permission = "documents.upload_own"

	// permManagerOfUnits is who may open unit folders besides the unit's own
	// people: the managers (org admin, site manager), not the board.
	permManagerOfUnits authz.Permission = "person.manage"
)

// AnyRead is the permission set of the read operations.
var AnyRead = authz.AnyOf(PermRead, PermReadAddressed)

// AnyWrite is the permission set of the write operations.
var AnyWrite = authz.AnyOf(PermManage, PermUploadOwn)

// Permissions declares the module's permissions; the wiring registers them.
func Permissions() []authz.PermissionDef {
	orgSite := []authz.ScopeType{authz.ScopeOrg, authz.ScopeSite}
	mgmt := []authz.Role{authz.RoleOrgAdmin, authz.RoleSiteManager, authz.RoleBoardMember}
	return []authz.PermissionDef{
		{Name: PermRead, Description: "Read folders and documents the caller's visibility allows",
			Roles: append(append([]authz.Role{}, mgmt...), authz.RoleAuditor), Scopes: orgSite,
			Occupants: []authz.OccupancyKind{authz.OccOwner, authz.OccTenant, authz.OccHousehold}},
		{Name: PermReadAddressed, Description: "Read only the documents recipient to the caller (closing statement, debt certificate); no folders",
			Scopes: orgSite, Former: true},
		{Name: PermManage, Description: "Create folders, upload, move and delete documents", Roles: mgmt, Scopes: orgSite},
		{Name: PermUploadOwn, Description: "Upload documents into the private folder of the caller's own unit",
			Scopes: orgSite, Occupants: []authz.OccupancyKind{authz.OccOwner, authz.OccTenant}},
	}
}

// TxRunner is the database access the module needs, satisfied by *db.DB.
type TxRunner interface {
	InTenantTx(ctx context.Context, orgID uuid.UUID, fn func(pgx.Tx) error) error
}

// Service is the documents module.
type Service struct {
	db    TxRunner
	files *files.Service
}

// NewService returns a Service and registers the "document" visibility
// resolver with the file module.
func NewService(db TxRunner, fs *files.Service) *Service {
	s := &Service{db: db, files: fs}
	if fs != nil {
		fs.RegisterResolver("document", resolver{s})
	}
	return s
}

// Visibility levels.
const (
	LevelBoard    = "board"
	LevelOwners   = "owners"
	LevelEveryone = "everyone"
	LevelUnits    = "units"
)

// Visibility says who may see a folder or document.
type Visibility struct {
	Level   string      `json:"level"`
	UnitIDs []uuid.UUID `json:"unit_ids,omitempty"`
}

func checkVisibility(v Visibility, field string) error {
	if !slices.Contains([]string{LevelBoard, LevelOwners, LevelEveryone, LevelUnits}, v.Level) {
		return problem.Validation(problem.Field{Field: field + ".level", Code: "invalid_value"})
	}
	if v.Level == LevelUnits && len(v.UnitIDs) == 0 {
		return problem.Validation(problem.Field{Field: field + ".unit_ids", Code: "required"})
	}
	if v.Level != LevelUnits && len(v.UnitIDs) > 0 {
		return problem.Validation(problem.Field{Field: field + ".unit_ids", Code: "not_allowed"})
	}
	return nil
}

func (s *Service) unitsExist(ctx context.Context, tx pgx.Tx, orgID, siteID uuid.UUID, ids []uuid.UUID, field string) error {
	if len(ids) == 0 {
		return nil
	}
	uniq := map[uuid.UUID]bool{}
	for _, u := range ids {
		uniq[u] = true
	}
	var n int
	if err := tx.QueryRow(ctx, `SELECT count(*) FROM unit WHERE org_id = $1 AND site_id = $2 AND id = ANY($3)`, orgID, siteID, ids).Scan(&n); err != nil {
		return err
	}
	if n != len(uniq) {
		return problem.Validation(problem.Field{Field: field + ".unit_ids", Code: "invalid_value"})
	}
	return nil
}

// access is what the caller may see of one site's document area.
type access struct {
	scope     authz.Scope
	siteID    uuid.UUID
	person    uuid.UUID
	read      bool // documents.read
	recipient bool // documents.read_addressed
	manage    bool
	uploadOwn bool
	board     bool // read or manage through a role, not only as a resident
	managerOf bool // may open every unit folder
	units     []uuid.UUID
	ownerUnit bool        // owns a unit of the site
	ownUnits  []uuid.UUID // units the caller owns or rents
}

func (s *Service) accessOf(ctx context.Context, tx pgx.Tx, orgID, siteID uuid.UUID) (access, error) {
	sc, err := opsx.SiteScope(ctx, tx, siteID)
	if err != nil {
		return access{}, err
	}
	if _, err := opsx.RequireAny(ctx, sc, AnyRead, AnyWrite); err != nil {
		return access{}, err
	}
	a := access{scope: sc, siteID: siteID, read: authz.Has(ctx, PermRead, sc), recipient: authz.Has(ctx, PermReadAddressed, sc),
		manage: authz.Has(ctx, PermManage, sc), uploadOwn: authz.Has(ctx, PermUploadOwn, sc),
		managerOf: authz.Has(ctx, permManagerOfUnits, sc)}
	g := authz.GrantsFromContext(ctx)
	a.board = g.HasViaRole(PermRead, sc) || g.HasViaRole(PermManage, sc)
	for _, o := range g.Current() {
		if o.SiteID != siteID {
			continue
		}
		a.units = append(a.units, o.UnitID)
		if o.Kind == authz.OccOwner {
			a.ownerUnit = true
		}
		if o.Kind == authz.OccOwner || o.Kind == authz.OccTenant {
			a.ownUnits = append(a.ownUnits, o.UnitID)
		}
	}
	if p, ok, err := opsx.PersonOf(ctx, tx, orgID); err != nil {
		return a, err
	} else if ok {
		a.person = p
	}
	return a, nil
}

func (a access) levelOK(v Visibility) bool {
	if a.board || a.manage {
		return true
	}
	if !a.read {
		return false
	}
	switch v.Level {
	case LevelOwners:
		return a.ownerUnit
	case LevelEveryone:
		return len(a.units) > 0
	case LevelUnits:
		for _, u := range v.UnitIDs {
			if slices.Contains(a.units, u) {
				return true
			}
		}
	}
	return false
}

// Folder is a site folder or the private folder of a unit.
type Folder struct {
	ID         uuid.UUID  `json:"id"`
	OrgID      uuid.UUID  `json:"org_id"`
	SiteID     uuid.UUID  `json:"site_id"`
	ParentID   *uuid.UUID `json:"parent_id"`
	Name       string     `json:"name"`
	Kind       string     `json:"kind"`
	UnitID     *uuid.UUID `json:"unit_id"`
	Visibility Visibility `json:"visibility"`
	Breadcrumb []Crumb    `json:"breadcrumb"`
	IsSystem   bool       `json:"is_system"`
	CreatedAt  time.Time  `json:"created_at"`
	UpdatedAt  time.Time  `json:"updated_at"`
	Version    int        `json:"version"`
	systemKey  *string
}

// Crumb is one step of a folder's path.
type Crumb struct {
	ID   uuid.UUID `json:"id"`
	Name string    `json:"name"`
}

const folderColumns = `id, org_id, site_id, parent_id, name, kind, unit_id, visibility_level, visibility_unit_ids, is_system, system_key, created_at, updated_at, version`

func scanFolder(row pgx.Row) (Folder, error) {
	var f Folder
	err := row.Scan(&f.ID, &f.OrgID, &f.SiteID, &f.ParentID, &f.Name, &f.Kind, &f.UnitID, &f.Visibility.Level, &f.Visibility.UnitIDs, &f.IsSystem, &f.systemKey, &f.CreatedAt, &f.UpdatedAt, &f.Version)
	f.CreatedAt, f.UpdatedAt = f.CreatedAt.UTC(), f.UpdatedAt.UTC()
	if f.Kind == "unit" && f.UnitID != nil {
		f.Visibility = Visibility{Level: LevelUnits, UnitIDs: []uuid.UUID{*f.UnitID}}
	}
	return f, err
}

// tree holds a site's folders in memory (a few hundred at most: one per unit).
type tree map[uuid.UUID]Folder

func loadTree(ctx context.Context, tx pgx.Tx, orgID, siteID uuid.UUID) (tree, error) {
	rows, err := tx.Query(ctx, `SELECT `+folderColumns+` FROM folder WHERE org_id = $1 AND site_id = $2`, orgID, siteID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	t := tree{}
	for rows.Next() {
		f, err := scanFolder(rows)
		if err != nil {
			return nil, err
		}
		t[f.ID] = f
	}
	return t, rows.Err()
}

func (t tree) path(id uuid.UUID) []Crumb {
	var out []Crumb
	seen := map[uuid.UUID]bool{}
	for cur := &id; cur != nil && !seen[*cur]; {
		f, ok := t[*cur]
		if !ok {
			break
		}
		seen[*cur] = true
		out = append([]Crumb{{ID: f.ID, Name: f.Name}}, out...)
		cur = f.ParentID
	}
	return out
}

// folderVisible: every folder on the way down must be open to the caller.
func (a access) folderVisible(t tree, id uuid.UUID) bool {
	seen := map[uuid.UUID]bool{}
	for cur := &id; cur != nil; {
		f, ok := t[*cur]
		if !ok || seen[*cur] {
			return false
		}
		seen[*cur] = true
		if f.Kind == "unit" {
			if !a.managerOf && (f.UnitID == nil || !slices.Contains(a.ownUnits, *f.UnitID)) {
				return false
			}
		} else if !a.levelOK(f.Visibility) {
			return false
		}
		cur = f.ParentID
	}
	return true
}

func ensureUnitFolders(ctx context.Context, tx pgx.Tx, orgID, siteID uuid.UUID) error {
	_, err := tx.Exec(ctx, `INSERT INTO folder (id, org_id, site_id, name, kind, unit_id, visibility_level, is_system)
		SELECT gen_random_uuid(), u.org_id, u.site_id, u.door_number, 'unit', u.id, 'units', true FROM unit u
		WHERE u.org_id = $1 AND u.site_id = $2 AND NOT EXISTS (SELECT 1 FROM folder f WHERE f.org_id = u.org_id AND f.unit_id = u.id)
		ON CONFLICT DO NOTHING`, orgID, siteID)
	return err
}

func (s *Service) folderSite(ctx context.Context, tx pgx.Tx, orgID, folderID uuid.UUID) (uuid.UUID, error) {
	var site uuid.UUID
	err := tx.QueryRow(ctx, `SELECT site_id FROM folder WHERE org_id = $1 AND id = $2`, orgID, folderID).Scan(&site)
	if errors.Is(err, pgx.ErrNoRows) {
		return uuid.Nil, problem.NotFound("no such folder")
	}
	return site, err
}

// ListFolders lists the folders of a site the caller may open (a former
// occupant sees none).
func (s *Service) ListFolders(ctx context.Context, orgID, siteID uuid.UUID, parent *uuid.UUID, kind string, unit *uuid.UUID, p tenancy.PageParams) ([]Folder, string, error) {
	limit, after, err := p.Resolve()
	if err != nil {
		return nil, "", err
	}
	var out []Folder
	err = s.db.InTenantTx(ctx, orgID, func(tx pgx.Tx) error {
		a, err := s.accessOf(ctx, tx, orgID, siteID)
		if err != nil {
			return err
		}
		if !a.read && !a.manage {
			return nil // documents.read_addressed alone: no folders
		}
		if err := ensureUnitFolders(ctx, tx, orgID, siteID); err != nil {
			return err
		}
		t, err := loadTree(ctx, tx, orgID, siteID)
		if err != nil {
			return err
		}
		all := make([]Folder, 0, len(t))
		for _, f := range t {
			all = append(all, f)
		}
		slices.SortFunc(all, func(x, y Folder) int { return strings.Compare(x.ID.String(), y.ID.String()) })
		for _, f := range all {
			if after != uuid.Nil && f.ID.String() <= after.String() {
				continue
			}
			if parent != nil && (f.ParentID == nil || *f.ParentID != *parent) {
				continue
			}
			if kind != "" && f.Kind != kind || unit != nil && (f.UnitID == nil || *f.UnitID != *unit) {
				continue
			}
			if !a.folderVisible(t, f.ID) {
				continue
			}
			f.Breadcrumb = t.path(f.ID)
			out = append(out, f)
			if len(out) == limit+1 {
				break
			}
		}
		return nil
	})
	if err != nil {
		return nil, "", tenancy.DBProblem(err, "folders")
	}
	items, next := tenancy.Page(out, limit, func(f Folder) uuid.UUID { return f.ID })
	return items, next, nil
}

func (s *Service) loadFolder(ctx context.Context, tx pgx.Tx, orgID, folderID uuid.UUID, forUpdate bool) (Folder, access, tree, error) {
	site, err := s.folderSite(ctx, tx, orgID, folderID)
	if err != nil {
		return Folder{}, access{}, nil, err
	}
	a, err := s.accessOf(ctx, tx, orgID, site)
	if err != nil {
		return Folder{}, a, nil, err
	}
	t, err := loadTree(ctx, tx, orgID, site)
	if err != nil {
		return Folder{}, a, nil, err
	}
	if (!a.read && !a.manage) || !a.folderVisible(t, folderID) {
		return Folder{}, a, t, problem.NotFound("no such folder")
	}
	f := t[folderID]
	if forUpdate {
		var v int
		if err := tx.QueryRow(ctx, `SELECT version FROM folder WHERE org_id = $1 AND id = $2 FOR UPDATE`, orgID, folderID).Scan(&v); err != nil {
			return f, a, t, err
		}
		f.Version = v
	}
	f.Breadcrumb = t.path(f.ID)
	return f, a, t, nil
}

// GetFolder returns a folder the caller may open.
func (s *Service) GetFolder(ctx context.Context, orgID, folderID uuid.UUID) (Folder, error) {
	var f Folder
	err := s.db.InTenantTx(ctx, orgID, func(tx pgx.Tx) error {
		var err error
		f, _, _, err = s.loadFolder(ctx, tx, orgID, folderID, false)
		return err
	})
	return f, tenancy.DBProblem(err, "folder")
}

func parseVisibility(d tenancy.Doc, key string) (*Visibility, bool, error) {
	if !d.Has(key) {
		return nil, false, nil
	}
	if d.IsNull(key) {
		return nil, true, nil
	}
	var v Visibility
	if err := d.Get(key, &v); err != nil {
		return nil, true, err
	}
	if err := checkVisibility(v, key); err != nil {
		return nil, true, err
	}
	return &v, true, nil
}

func uuidOf(d tenancy.Doc, key string) (*uuid.UUID, bool, error) {
	if !d.Has(key) {
		return nil, false, nil
	}
	sp, err := d.String(key)
	if err != nil || sp == nil {
		return nil, true, err
	}
	u, perr := uuid.Parse(*sp)
	if perr != nil {
		return nil, true, problem.Validation(problem.Field{Field: key, Code: "invalid_format"})
	}
	return &u, true, nil
}

func cleanName(n string, field string) (string, error) {
	n = strings.TrimSpace(n)
	if l := len([]rune(n)); l < 1 || l > 120 {
		return "", problem.Validation(problem.Field{Field: field, Code: "invalid_length"})
	}
	return n, nil
}

// CreateFolder adds a site folder (documents.manage). It starts board-only
// unless a visibility is given.
func (s *Service) CreateFolder(ctx context.Context, orgID uuid.UUID, d tenancy.Doc) (Folder, error) {
	if bad := d.Unknown("site_id", "parent_id", "name", "visibility"); len(bad) > 0 {
		return Folder{}, problem.Validation(bad...)
	}
	siteID, _, err := uuidOf(d, "site_id")
	if err != nil {
		return Folder{}, err
	}
	if siteID == nil {
		return Folder{}, problem.Validation(problem.Field{Field: "site_id", Code: "required"})
	}
	parent, _, err := uuidOf(d, "parent_id")
	if err != nil {
		return Folder{}, err
	}
	np, err := d.String("name")
	if err != nil {
		return Folder{}, err
	}
	name, err := cleanName(deref(np), "name")
	if err != nil {
		return Folder{}, err
	}
	vis, _, err := parseVisibility(d, "visibility")
	if err != nil {
		return Folder{}, err
	}
	var out Folder
	err = s.db.InTenantTx(ctx, orgID, func(tx pgx.Tx) error {
		a, err := s.accessOf(ctx, tx, orgID, *siteID)
		if err != nil {
			return err
		}
		if !a.manage {
			return problem.Forbidden("you need documents.manage")
		}
		if err := ensureUnitFolders(ctx, tx, orgID, *siteID); err != nil {
			return err
		}
		if parent != nil {
			var kind string
			if err := tx.QueryRow(ctx, `SELECT kind FROM folder WHERE org_id = $1 AND site_id = $2 AND id = $3`, orgID, *siteID, *parent).Scan(&kind); err != nil || kind != "site" {
				return problem.Validation(problem.Field{Field: "parent_id", Code: "invalid_value"})
			}
		}
		v := Visibility{Level: LevelBoard}
		if vis != nil {
			v = *vis
		}
		if err := s.unitsExist(ctx, tx, orgID, *siteID, v.UnitIDs, "visibility"); err != nil {
			return err
		}
		fid := id.New()
		if _, err := tx.Exec(ctx, `INSERT INTO folder (id, org_id, site_id, parent_id, name, visibility_level, visibility_unit_ids) VALUES ($1, $2, $3, $4, $5, $6, $7)`,
			fid, orgID, *siteID, parent, name, v.Level, nilIfEmpty(v.UnitIDs)); err != nil {
			return err
		}
		out, _, _, err = s.loadFolder(ctx, tx, orgID, fid, false)
		if err != nil {
			return err
		}
		return recordFolder(ctx, tx, "documents.folder_create", nil, out)
	})
	return out, tenancy.DBProblem(err, "folder")
}

func nilIfEmpty(u []uuid.UUID) []uuid.UUID {
	if u == nil {
		return []uuid.UUID{}
	}
	return u
}

func deref(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func recordFolder(ctx context.Context, tx pgx.Tx, action string, before *Folder, after Folder) error {
	view := func(f Folder) map[string]any {
		return map[string]any{"name": f.Name, "parent_id": f.ParentID, "visibility": f.Visibility.Level, "visibility_units": len(f.Visibility.UnitIDs)}
	}
	var b any
	if before != nil {
		b = view(*before)
	}
	diff, _ := audit.Diff("folder", b, view(after))
	site := after.SiteID
	return audit.Record(ctx, tx, audit.Event{OrgID: after.OrgID, SiteID: &site, Action: action, TargetType: "folder", TargetID: after.ID, Diff: diff})
}

// UpdateFolder renames, moves or changes the visibility of a folder
// (documents.manage). System folders (unit folders and the folders generated
// documents land in) cannot be changed (409).
func (s *Service) UpdateFolder(ctx context.Context, orgID, folderID uuid.UUID, expected int, d tenancy.Doc) (Folder, error) {
	if bad := d.Unknown("parent_id", "name", "visibility"); len(bad) > 0 {
		return Folder{}, problem.Validation(bad...)
	}
	var out Folder
	err := s.db.InTenantTx(ctx, orgID, func(tx pgx.Tx) error {
		before, a, t, err := s.loadFolder(ctx, tx, orgID, folderID, true)
		if err != nil {
			return err
		}
		if !a.manage {
			return problem.Forbidden("you need documents.manage")
		}
		if before.Version != expected {
			return tenancy.ErrVersion
		}
		if before.IsSystem {
			return problem.Conflict("a system folder cannot be changed")
		}
		next := before
		if d.Has("name") {
			np, err := d.String("name")
			if err != nil {
				return err
			}
			if next.Name, err = cleanName(deref(np), "name"); err != nil {
				return err
			}
		}
		if p, ok, err := uuidOf(d, "parent_id"); err != nil {
			return err
		} else if ok {
			if p != nil {
				pf, found := t[*p]
				if !found || pf.Kind != "site" {
					return problem.Validation(problem.Field{Field: "parent_id", Code: "invalid_value"})
				}
				for _, c := range t.path(*p) { // no cycles: the new parent must not be below this folder
					if c.ID == folderID {
						return problem.Validation(problem.Field{Field: "parent_id", Code: "invalid_value"})
					}
				}
			}
			next.ParentID = p
		}
		if v, ok, err := parseVisibility(d, "visibility"); err != nil {
			return err
		} else if ok {
			if v == nil {
				return problem.Validation(problem.Field{Field: "visibility", Code: "required"})
			}
			if err := s.unitsExist(ctx, tx, orgID, before.SiteID, v.UnitIDs, "visibility"); err != nil {
				return err
			}
			next.Visibility = *v
		}
		if _, err := tx.Exec(ctx, `UPDATE folder SET parent_id = $3, name = $4, visibility_level = $5, visibility_unit_ids = $6, updated_at = now(), version = version + 1 WHERE org_id = $1 AND id = $2`,
			orgID, folderID, next.ParentID, next.Name, next.Visibility.Level, nilIfEmpty(next.Visibility.UnitIDs)); err != nil {
			return err
		}
		out, _, _, err = s.loadFolder(ctx, tx, orgID, folderID, false)
		if err != nil {
			return err
		}
		return recordFolder(ctx, tx, "documents.folder_update", &before, out)
	})
	return out, tenancy.DBProblem(err, "folder")
}

// DeleteFolder removes an empty, non-system folder.
func (s *Service) DeleteFolder(ctx context.Context, orgID, folderID uuid.UUID, expected int) error {
	err := s.db.InTenantTx(ctx, orgID, func(tx pgx.Tx) error {
		before, a, _, err := s.loadFolder(ctx, tx, orgID, folderID, true)
		if err != nil {
			return err
		}
		if !a.manage {
			return problem.Forbidden("you need documents.manage")
		}
		if before.Version != expected {
			return tenancy.ErrVersion
		}
		if before.IsSystem {
			return problem.Conflict("a system folder cannot be deleted")
		}
		var n int
		if err := tx.QueryRow(ctx, `SELECT (SELECT count(*) FROM folder WHERE org_id = $1 AND parent_id = $2) + (SELECT count(*) FROM document WHERE org_id = $1 AND folder_id = $2)`, orgID, folderID).Scan(&n); err != nil {
			return err
		}
		if n > 0 {
			return problem.Conflict("the folder is not empty")
		}
		if _, err := tx.Exec(ctx, `DELETE FROM folder WHERE org_id = $1 AND id = $2`, orgID, folderID); err != nil {
			return err
		}
		return recordFolder(ctx, tx, "documents.folder_delete", &before, Folder{ID: folderID, OrgID: orgID, SiteID: before.SiteID, Name: before.Name})
	})
	return tenancy.DBProblem(err, "folder")
}
